//! 📝️ Planner requirements precede numeric interpretation of private original identity drafts.
use super::*;
pub(super) struct IdentityDraftState{pub requirements:[Option<(usize,bool)>;MAXIMUM_IDENTITIES],pub count:usize,pub index:usize,pub seen:[bool;MAXIMUM_IDENTITIES],pub queried:bool,pub draft:bool,pub full:bool}
impl Default for IdentityDraftState{fn default()->Self{Self{requirements:[None;MAXIMUM_IDENTITIES],count:0,index:0,seen:[false;MAXIMUM_IDENTITIES],queried:false,draft:false,full:false}}}
pub(super) fn rows(value:&DslValue)->Result<&[DslValue],ValueError>{let DslValue::Object(fields)=value else{return Err(refused())};if fields.len()>8{return Err(refused());}match fields.iter().find(|(key,_)|key=="identities").map(|(_,value)|value){Some(DslValue::Array(rows))if rows.len()<=MAXIMUM_IDENTITIES=>Ok(rows),_=>Err(refused())}}
pub(super) fn fields(value:&DslValue)->Result<(&str,Option<&str>,Option<&str>),ValueError>{let DslValue::Object(fields)=value else{return Err(refused())};if fields.len()>3{return Err(refused());}let mut key=None;let mut id=None;let mut guid=None;for(name,value)in fields{let DslValue::String(value)=value else{return Err(refused())};match name.as_str(){"key" if key.is_none()=>key=Some(value.as_str()),"id" if id.is_none()=>id=Some(value.as_str()),"guid" if guid.is_none()=>guid=Some(value.as_str()),_=>return Err(refused())}}Ok((key.ok_or_else(refused)?,id,guid))}
fn canonical(value:&str)->bool{!value.is_empty()&&value.len()<=20&&value.as_bytes()[0]!=b'0'&&value.bytes().all(|byte|byte.is_ascii_digit())&&(value.len()<20||value<="18446744073709551615")}
impl IfcTemplateSourceWork{
    pub(super) fn advance_identity(&mut self,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{
        match self.phase{
            25=>{let copy=self.copy.as_mut().ok_or_else(refused)?;let DslValue::Object(fields)=copy else{return Err(refused().into())};if fields.len()>8{return Err(refused().into());}let slot=fields.iter_mut().find(|(key,_)|key=="identities").map(|(_,value)|value).ok_or_else(refused)?;if !matches!(&*slot,DslValue::Array(rows)if rows.len()<=MAXIMUM_IDENTITIES){return Err(refused().into());}metadata(cx,2*size_of::<DslValue>(),||{*self.discarded=Some(std::mem::replace(slot,DslValue::Array(Vec::new())));self.phase=3;})?;},
            26=>{let count=self.query.planner.identity_count().ok_or_else(refused)?;if self.identities.index<count{self.identities.requirements[self.identities.index]=self.query.planner.identity_requirement(self.identities.index);self.identities.index+=1;}else{self.identities.count=count;self.identities.index=0;self.identities.queried=true;self.phase=27;}},
            27=>{let raw=&self.source.as_ref().ok_or_else(refused)?.try_authority()?.args;let rows=rows(raw)?;if self.identities.index==rows.len(){if rows.len()!=self.identities.count||self.identities.seen[..self.identities.count].iter().any(|seen|!seen){self.identities.draft=true;}self.phase=if self.identities.draft{7}else{28};return Ok(());}let index=self.identities.index;let(key,id,guid)=fields(&rows[index])?;let position=self.identities.requirements[..self.identities.count].iter().position(|row|row.is_some_and(|(encoded,_)|key_matches(encoded,key)));if let Some(position)=position{let(_,rooted)=self.identities.requirements[position].unwrap();if self.identities.seen[position]||rooted!=guid.is_some()||guid.is_some_and(|value|!super::super::super::guid(value)){self.identities.draft=true;}self.identities.seen[position]=true;}else{self.identities.draft=true;}if id.is_none_or(|value|!canonical(value)){self.identities.draft=true;}for previous in &rows[..index]{let(_,previous_id,previous_guid)=fields(previous)?;if id.is_some_and(canonical)&&previous_id==id||guid.is_some_and(super::super::super::guid)&&previous_guid==guid{self.identities.draft=true;}}self.identities.index+=1;},
            28=>{if !self.clone.terminal_is_empty(){let demand=self.clone.selected_close_demand(4096)?;semio_framework_job::close_original_retained_step(cx,demand,|grant|self.clone.close_step(grant))?;}else{metadata(cx,2*size_of::<RetainedCloneOwner<DslValue>>(),||{self.clone=Default::default();self.identities.full=true;self.phase=1;})?;}},
            29=>{if self.full.receiver.receive_owned(&mut self.copy,cx)?{self.phase=30;}},
            30=>{if self.full.receiver.advance(cx)?{self.phase=31;}},
            31=>{if self.full.receiver.take(&mut self.full.planner.application,cx)?{self.phase=32;}},
            32=>{metadata(cx,2*size_of::<Vec<IfcTemplateIdentity>>(),||{self.query.planner.application.as_mut().unwrap().identities=std::mem::take(&mut self.full.planner.application.as_mut().unwrap().identities);self.phase=6;})?;},
            40=>{if reserve(&mut self.page.as_mut().unwrap().status.diagnostics,1,cx)?{self.phase=41;}},
            41=>{metadata(cx,size_of::<StagedFormDiagnostic>(),||{self.page.as_mut().unwrap().status.diagnostics.push(StagedFormDiagnostic{path:Vec::new(),code:String::new(),label:StagedFormLabel{en:String::new(),de:String::new()}});self.phase=42;})?;},
            42=>{let diagnostic=&mut self.page.as_mut().unwrap().status.diagnostics[0];if reserve(&mut diagnostic.path,1,cx)?{self.phase=43;}},
            43=>{let diagnostic=&mut self.page.as_mut().unwrap().status.diagnostics[0];if diagnostic.path.is_empty(){metadata(cx,size_of::<String>(),||diagnostic.path.push(String::new()))?;}else if copy_text(&mut diagnostic.path[0],"identities",cx)?{self.phase=44;}},
            44=>{if copy_text(&mut self.page.as_mut().unwrap().status.diagnostics[0].code,"template.identities",cx)?{self.phase=45;}},
            45=>{if copy_text(&mut self.page.as_mut().unwrap().status.diagnostics[0].label.en,"Retain every planner identity with an available id and required GlobalId",cx)?{self.phase=46;}},
            46=>{if copy_text(&mut self.page.as_mut().unwrap().status.diagnostics[0].label.de,"Jede Planeridentität mit verfügbarer ID und erforderlicher GlobalId festlegen",cx)?{self.phase=11;}},
            _=>return Err(refused().into()),
        }Ok(())
    }
}
